// === Tab: mySketch ===
//-- Simple(?) let Motion Experiments
//-- Siddhartha, 29th Sept, 2019, let int N = 200;
let ntri = 8;
let rad = 300.0;
let dt = 0.0;
color [] cols = {"#a31621", "#faa916", "#e09f3e", "#fb4b4e"};

geometry g1;

function setup() {
  // createCanvas(1000, 1000);
  createCanvas(windowWidth, windowHeight, WEBGL);
  background(0);
  g1 = new geometry();  

}

function draw() {
  noStroke();
  fill(0,80);
  rect(0,0,width,height);

  g1.move();
  g1.show();
  //g1.connect();

  dt += 0.1;

  edges();

}

function edges() {
  stroke(cols[1]);  
  line(width/2 + rad -50, height/2 - rad - 35, width/2 + rad + 50 + 35, height/2 - rad - 35);
  line(width/2 + rad -50, height/2 + rad + 35, width/2 + rad + 50 + 35, height/2 + rad + 35);  
  line(width/2 - rad -50 -35, height/2 - rad - 35, width/2 - rad + 50, height/2 - rad - 35);
  line(width/2 - rad -50 -35, height/2 + rad + 35, width/2 - rad + 50, height/2 + rad + 35);

  line(width/2 + rad + 50, height/2 - rad -50-20, width/2 + rad + 50, height/2 -rad + 50 + 20);
  line(width/2 - rad - 50, height/2 - rad -50-20, width/2 - rad - 50, height/2 -rad + 50 + 20);

  line(width/2 + rad + 50, height/2 + rad -50-20, width/2 + rad + 50, height/2 +rad + 50 + 20);
  line(width/2 - rad - 50, height/2 + rad -50-20, width/2 - rad - 50, height/2 +rad + 50 + 20);

}

// === Tab: tab2 ===
class geometry{
  //-- let float [] xc;
  float [] yc;
  float [] phase;
  float [] rad2;
  color [] shade;
  float [] size;

  constructor() {
    //-- let xc = new Array(N);
    yc = new Array(N);
    phase = new Array(N);
    rad2 = new Array(N);
    shade = new Array(N);
    size = new Array(N);

    for(i=0; i<N; ++i){
      xc[i] = width/2 + rad*cos( TWO_PI*i/N );
      yc[i] = height/2 + rad*sin( TWO_PI*i/N );
      phase[i] = random(TWO_PI);
      size[i] = random(1,40);
      rad2[i] = random(8.0, 20.0);
      shade[i] = cols[int(random(cols.length))];
    }
  }//-- let the Initializations

  //-- let function show() {
  for(i=0; i<N; ++i){
      stroke(shade[i]);
      let d = pow((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - xc[i],2.0) + pow((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - yc[i],2.0);
      if (d>2500){
        ellipse(xc[i], yc[i], size[i]*sin(dt*rad2[i]/20.0 + phase[i]), size[i]*sin(dt*rad2[i]/20.0 + phase[i]));
        ellipse(xc[i], yc[i], 3, 3);
      } else {
        ellipse(xc[i], yc[i], size[i]*sin(dt*rad2[i]/5.0 + phase[i]), size[i]*sin(dt + phase[i]));
      }
    }
  }

  function connect() {
    strokeWeight(1);  
    for(i=0; i<N; ++i) {
      for(j=i; j<N; ++j) {
        stroke(shade[i]);
        line(xc[i], yc[i], xc[j], yc[j]);
      }
    }

  for(i=0; i<ntri; ++i) {
    noStroke();
    fill(cols[int(random(cols.length))],100);
    triangle(xc[i],yc[i],xc[(i+1)%N], yc[(i+1)%N], xc[(i+2)%N], yc[(i+2)%N]);
    }
  }

  function move() {
    for(i=0; i<N; ++i){

      xc[i] = width/2 + rad*cos( TWO_PI*i/N + phase[i] + dt*0.02 ) + rad2[i]*cos( phase[i] + dt );
      yc[i] = height/2 + rad*sin( TWO_PI*i/N + dt*0.02 ) + 0.1*rad2[i]*sin( phase[i] + dt ); 
    }
  }

}

